# Polyglot Academy 5.5 voice UI patch, sha256-verified.
# Reproduces the tested, complete Android UI patch against the original 5.4 release.
from pathlib import Path
import base64, gzip, hashlib
source = gzip.decompress(base64.b64decode(""))
assert hashlib.sha256(source).hexdigest() == "fa0e5b504d9d1c2a3f95e2fc46d884ba1494f235d05af3e819de307604875185", "Patch integrity failure"
p = Path(__file__).resolve().parent.parent / "patch_55.py"
exec(compile(source.decode("utf-8"), str(p), "exec"), {"__file__": str(p), "__name__": "__main__"})
